<?php session_start(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login — Solomon</title><link rel="stylesheet" href="assets/css/main.css"></head><body><main class="panel"><h1>SOLOMON LOGIN</h1><form id="form"><input name="username" placeholder="Username or email" required><input name="password" type="password" placeholder="Password" required><button class="btn">LOGIN</button><p id="msg"></p></form><a href="register.php">Create account</a></main><script>form.onsubmit=async e=>{e.preventDefault();let r=await fetch('api/login.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});let d=await r.json();msg.textContent=d.message||'Success';if(d.success)location.href='dashboard.php';}</script></body></html>
